CREATE OR REPLACE FUNCTION private.design_input_validation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$ DECLARE a jsonb; p text; bytes bigint:=0; actual bigint; BEGIN IF TG_OP='UPDATE' AND NEW.data->'inputAttachments' IS NOT DISTINCT FROM OLD.data->'inputAttachments' AND NEW.data->'productIds' IS NOT DISTINCT FROM OLD.data->'productIds' THEN RETURN NEW; END IF; IF NEW.data ? 'productIds' AND jsonb_typeof(NEW.data->'productIds')='array' AND (SELECT count(*) FROM jsonb_array_elements_text(NEW.data->'productIds'))<>(SELECT count(DISTINCT v) FROM jsonb_array_elements_text(NEW.data->'productIds') v) THEN RAISE EXCEPTION 'Sản phẩm bị chọn trùng'; END IF; IF jsonb_typeof(NEW.data->'inputAttachments')='array' THEN FOR a IN SELECT value FROM jsonb_array_elements(NEW.data->'inputAttachments') LOOP IF a->>'kind'='link' THEN IF coalesce(a->>'url','') !~ '^https?://[^/@[:space:]]+([/:?#]|$)' OR a->>'url' ~ '^https?://[^/]*@' THEN RAISE EXCEPTION 'Link không hợp lệ'; END IF; ELSE p:=a->>'path'; SELECT (metadata->>'size')::bigint INTO actual FROM storage.objects WHERE bucket_id='design-inputs' AND name=p; IF actual IS NULL OR actual<=0 OR actual>20971520 OR lower(p) !~ '\.(pdf|doc|docx|xls|xlsx|ppt|pptx|jpg|jpeg|png|webp|gif|heic|ai|psd|eps|svg|tif|tiff|zip|txt|csv)$' THEN RAISE EXCEPTION 'Tệp không hợp lệ hoặc vượt quá 20 MB'; END IF; bytes:=bytes+actual; IF bytes>104857600 THEN RAISE EXCEPTION 'Tổng tệp của Order vượt quá 100 MB'; END IF; END IF; END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER design_order_zz_input_validation BEFORE INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION private.design_input_validation();